def zeilen_vier():
    """Fuer gen_i18n.py: Kennung, en, de, zh, ja."""
    return [z[:5] for z in ZEILEN]


def texte(sprache):
    """Fuer i18n_sprache_es.py / i18n_sprache_cs.py: Kennung -> Text."""
    nr = {"es": 5, "cs": 6}[sprache]
    return {z[0]: z[nr] for z in ZEILEN}
